package com.freeeats;

import static com.freeeats.cooldown.AnimationData.isManualCasting;

import com.freeeats.cooldown.AnimationData;
import com.freeeats.cooldown.AttackProcedure;
import com.freeeats.cooldown.AttackStyle;
import com.freeeats.cooldown.CastingSoundData;
import com.freeeats.cooldown.ClientUtils.Utils;
import com.freeeats.cooldown.PoweredStaves;
import com.freeeats.cooldown.Spellbook;
import com.freeeats.cooldown.VariableSpeed.VariableSpeed;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.NPCManager;

/**
 * Tracks the local player's attack cooldown without drawing a timer.
 *
 * Free Eats needs the "when can I attack again?" answer, including confirmed food delay.
 *
 * A food click is not enough proof because it can fail. The tracker waits for the game message, adds
 * the food attack delay on the next tick, and lets the overlay hide until the corrected cooldown is gone.
 */
final class AttackCooldownTracker
{
	private enum AttackState
	{
		NOT_ATTACKING,
		DELAYED_FIRST_TICK,
		DELAYED
	}

	private static final int ATTACK_DELAY_NONE = 0;
	private static final int SALAMANDER_SET_ANIM_ID = 952;
	private static final int TWINFLAME_STAFF_WEAPON_ID = 30634;
	private static final int ECHO_VENATOR_BOW_WEAPON_ID = 30434;
	private static final int VENATOR_BOW_WEAPON_ID = 27610;
	private static final int BLACK_GEM_KERIS_ID = 30891;

	private static final Map<Integer, Integer> NON_STANDARD_ATTACK_SPEEDS =
		new ImmutableMap.Builder<Integer, Integer>()
			.put(BLACK_GEM_KERIS_ID, 4)
			.build();

	private static final Map<Integer, Integer> NON_STANDARD_MAGIC_WEAPON_SPEEDS =
		new ImmutableMap.Builder<Integer, Integer>()
			.put(TWINFLAME_STAFF_WEAPON_ID, 6)
			.build();

	private static final Map<Integer, Integer> WEAPON_ID_MAPPING_WORKAROUNDS =
		new ImmutableMap.Builder<Integer, Integer>()
			.put(ECHO_VENATOR_BOW_WEAPON_ID, VENATOR_BOW_WEAPON_ID)
			.build();

	private static final Set<AnimationData> UNRELIABLE_ANIMATIONS =
		new ImmutableSet.Builder<AnimationData>()
			.add(AnimationData.RANGED_BLOWPIPE)
			.add(AnimationData.RANGED_BLAZING_BLOWPIPE)
			.add(AnimationData.MAGIC_EYE_OF_AYAK)
			.add(AnimationData.MAGIC_EYE_OF_AYAK_SPEC)
			.build();

	private static final List<Integer> SPECIAL_NPCS = Arrays.asList(10507, 9435, 9438, 9441, 9444);

	private final Client client;
	private final ItemManager itemManager;
	private final NPCManager npcManager;

	private int tickPeriod;
	private int attackDelayHoldoffTicks = ATTACK_DELAY_NONE;
	private int pendingFoodDelayTicks;
	private int lastUsedWeaponId = -1;
	private int soundEffectTick = -1;
	private int soundEffectId = -1;
	private boolean usingMagic;
	private Spellbook currentSpellBook = Spellbook.STANDARD;
	private AttackState attackState = AttackState.NOT_ATTACKING;
	private AttackState renderedState = AttackState.NOT_ATTACKING;

	private final ArrayDeque<Integer> specialPercentageEvents = new ArrayDeque<>();
	private final Map<Skill, ArrayDeque<Integer>> combatExpEarned = Map.of(
		Skill.MAGIC, new ArrayDeque<>(),
		Skill.RANGED, new ArrayDeque<>(),
		Skill.DEFENCE, new ArrayDeque<>(),
		Skill.STRENGTH, new ArrayDeque<>(),
		Skill.ATTACK, new ArrayDeque<>()
	);

	@Inject
	AttackCooldownTracker(Client client, ItemManager itemManager, NPCManager npcManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.npcManager = npcManager;
	}

	void reset()
	{
		tickPeriod = 0;
		attackDelayHoldoffTicks = ATTACK_DELAY_NONE;
		pendingFoodDelayTicks = 0;
		lastUsedWeaponId = -1;
		soundEffectTick = -1;
		soundEffectId = -1;
		usingMagic = false;
		attackState = AttackState.NOT_ATTACKING;
		renderedState = AttackState.NOT_ATTACKING;
		specialPercentageEvents.clear();
		combatExpEarned.values().forEach(ArrayDeque::clear);
	}

	void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.SPELLBOOK)
		{
			currentSpellBook = Spellbook.fromVarbit(event.getValue());
		}

		if (event.getVarpId() == VarPlayerID.SA_ENERGY)
		{
			specialPercentageEvents.addLast(event.getValue());
		}
	}

	void onSoundEffectPlayed(SoundEffectPlayed event)
	{
		soundEffectTick = client.getTickCount();
		soundEffectId = event.getSoundId();
	}

	boolean onFakeXpDrop(FakeXpDrop event)
	{
		if (!combatExpEarned.containsKey(event.getSkill()))
		{
			return false;
		}

		combatExpEarned.get(event.getSkill()).addLast(event.getXp());
		if (inPreAttackWindow())
		{
			performAttack();
			return true;
		}

		return false;
	}

	boolean onStatChanged(StatChanged event)
	{
		if (!combatExpEarned.containsKey(event.getSkill()))
		{
			return false;
		}

		combatExpEarned.get(event.getSkill()).addLast(event.getXp());
		if (inPreAttackWindow())
		{
			performAttack();
			return true;
		}

		return false;
	}

	void onChatMessage(ChatMessage event)
	{
		pendingFoodDelayTicks += FoodAttackDelay.fromChatMessage(event.getMessage());
		VariableSpeed.onChatMessage(client, event);
	}

	boolean onInteractingChanged(InteractingChanged event)
	{
		Player localPlayer = client.getLocalPlayer();
		boolean attackStarted = false;

		if (localPlayer != null && localPlayer.equals(event.getSource()))
		{
			Actor target = event.getTarget();
			if ((target instanceof NPC || target instanceof Player)
				&& attackState == AttackState.NOT_ATTACKING
				&& isLocalPlayerAttacking())
			{
				usingMagic = false;
				performAttack();
				attackStarted = true;
			}
		}

		applyAndClearFoodDelay();
		return attackStarted;
	}

	boolean onGameTick(GameTick event)
	{
		VariableSpeed.onGameTick(client, event);
		boolean attackStarted = false;
		boolean attacking = isLocalPlayerAttacking();

		switch (attackState)
		{
			case NOT_ATTACKING:
				if (attacking)
				{
					performAttack();
					attackStarted = true;
				}
				break;
			case DELAYED_FIRST_TICK:
				attackState = AttackState.DELAYED;
				// fall through
			case DELAYED:
				if (attackDelayHoldoffTicks <= 0)
				{
					if (attacking)
					{
						performAttack();
						attackStarted = true;
					}
					else
					{
						attackState = AttackState.NOT_ATTACKING;
					}
				}
				break;
		}

			applyAndClearFoodDelay();
			attackDelayHoldoffTicks = Math.max(-20, attackDelayHoldoffTicks - 1);
			trimHistory();
			return attackStarted;
		}

	void onRender()
	{
		int delta = VariableSpeed.SHADOW_CRASH.onRender(client, attackDelayHoldoffTicks, usingMagic, false);
		if (delta != 0)
		{
			attackDelayHoldoffTicks += delta;
			if (attackDelayHoldoffTicks < 0)
			{
				attackState = AttackState.NOT_ATTACKING;
			}
		}

		checkForLateWeaponSwaps();
		renderedState = attackState;
	}

		int getTicksUntilNextAttack()
		{
			return 1 + attackDelayHoldoffTicks;
		}

		private void applyAndClearFoodDelay()
		{
			attackDelayHoldoffTicks += pendingFoodDelayTicks;
			pendingFoodDelayTicks = 0;
		}

	private void performAttack()
	{
		attackState = AttackState.DELAYED_FIRST_TICK;
		setAttackDelay();
		tickPeriod = attackDelayHoldoffTicks;
	}

	private void setAttackDelay()
	{
		int weaponId = getWeaponId();
		AnimationData animation = currentAnimation();
		PoweredStaves stave = PoweredStaves.getPoweredStaves(weaponId, animation);
		boolean matchesSpellbook = matchesSpellbook(animation);
		attackDelayHoldoffTicks = getWeaponSpeed(weaponId, stave, animation, matchesSpellbook);
		lastUsedWeaponId = weaponId;
	}

	private int getWeaponSpeed(int weaponId, PoweredStaves stave, AnimationData animation, boolean matchesSpellbook)
	{
		int specDelta = Utils.getLastDelta(specialPercentageEvents);
		int damageDealt = -1;

		if (stave != null && stave.getAnimations().contains(animation))
		{
			usingMagic = true;
			damageDealt = computeDamage(Utils.getAttackStyle(client), AttackProcedure.POWERED_STAVE, animation);
			return VariableSpeed.computeSpeed(client, animation, AttackProcedure.POWERED_STAVE, damageDealt, specDelta, 4);
		}

		if (matchesSpellbook && isManualCasting(animation))
		{
			usingMagic = true;
			damageDealt = computeDamage(Utils.getAttackStyle(client), AttackProcedure.MANUAL_AUTO_CAST, animation);
			return VariableSpeed.computeSpeed(client, animation, AttackProcedure.MANUAL_AUTO_CAST, damageDealt, specDelta, getMagicBaseSpeed(weaponId));
		}

		usingMagic = false;
		damageDealt = computeDamage(Utils.getAttackStyle(client), AttackProcedure.MELEE_OR_RANGE, animation);
		ItemStats weaponStats = getWeaponStats(weaponId);
		if (weaponStats == null)
		{
			return VariableSpeed.computeSpeed(client, animation, AttackProcedure.MELEE_OR_RANGE, damageDealt, specDelta, 4);
		}

		return VariableSpeed.computeSpeed(client, animation, AttackProcedure.MELEE_OR_RANGE, damageDealt, specDelta, weaponStats.getEquipment().getAspeed());
	}

	private int computeDamage(AttackStyle attackStyle, AttackProcedure attackProcedure, AnimationData animation)
	{
		switch (attackProcedure)
		{
			case POWERED_STAVE:
			case MELEE_OR_RANGE:
				return -1;
			case MANUAL_AUTO_CAST:
				if (attackStyle == AttackStyle.DEFENSIVE_CASTING || attackStyle == AttackStyle.DEFENSIVE)
				{
					return Utils.getLastDelta(combatExpEarned.get(Skill.DEFENCE));
				}

				int mageExp = Utils.getLastDelta(combatExpEarned.get(Skill.MAGIC));
				if (animation != AnimationData.MAGIC_ARCEUUS_DEMONBANE)
				{
					return -1;
				}

				return (int) Math.ceil(((double) mageExp - 43.5D) / 2.0D);
			default:
				return -1;
		}
	}

	private ItemStats getWeaponStats(int weaponId)
	{
		if (NON_STANDARD_ATTACK_SPEEDS.containsKey(weaponId))
		{
			return new ItemStats(true, -1, -1,
				ItemEquipmentStats.builder().aspeed(NON_STANDARD_ATTACK_SPEEDS.get(weaponId)).build());
		}

		return itemManager.getItemStats(weaponId);
	}

	private int getWeaponId()
	{
		int weaponId = Utils.getWeaponId(client);
		return WEAPON_ID_MAPPING_WORKAROUNDS.getOrDefault(weaponId, weaponId);
	}

	private int getMagicBaseSpeed(int weaponId)
	{
		return NON_STANDARD_MAGIC_WEAPON_SPEEDS.getOrDefault(weaponId, 5);
	}

	private boolean matchesSpellbook(AnimationData animation)
	{
		if (animation != null && animation.matchesSpellbook(currentSpellBook))
		{
			return true;
		}

		return client.getTickCount() == soundEffectTick
			&& CastingSoundData.getSpellBookFromId(soundEffectId) == currentSpellBook;
	}

	private boolean isLocalPlayerAttacking()
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return false;
		}

		int animationId = localPlayer.getAnimation();
		if (AnimationData.isBlockListAnimation(animationId))
		{
			return false;
		}

		boolean notWalking = animationId != -1 || localPlayer.hasSpotAnim(SALAMANDER_SET_ANIM_ID);
		Actor target = localPlayer.getInteracting();

		if (target instanceof NPC)
		{
			NPC npc = (NPC) target;
			boolean containsAttackOption = Arrays.stream(npc.getComposition().getActions()).anyMatch("Attack"::equals);
			Integer health = npcManager.getHealth(npc.getId());
			boolean hasHealthAndLevel = health != null && health > 0 && target.getCombatLevel() > 0;
			boolean attackingNpc = hasHealthAndLevel || SPECIAL_NPCS.contains(npc.getId()) || containsAttackOption;
			return attackingNpc && notWalking;
		}

		if (target instanceof Player)
		{
			return notWalking;
		}

		AnimationData animation = AnimationData.fromId(animationId);
		if (UNRELIABLE_ANIMATIONS.contains(animation))
		{
			return false;
		}

		return animation != null;
	}

	private AnimationData currentAnimation()
	{
		Player localPlayer = client.getLocalPlayer();
		return localPlayer == null ? null : AnimationData.fromId(localPlayer.getAnimation());
	}

	private void checkForLateWeaponSwaps()
	{
		boolean weaponMismatch = Utils.getWeaponId(client) != lastUsedWeaponId;
		if (inPreAttackWindow() && weaponMismatch)
		{
			performAttack();
		}
	}

	private boolean inPreAttackWindow()
	{
		return attackState == AttackState.DELAYED_FIRST_TICK && renderedState != attackState;
	}

	private void trimHistory()
	{
		if (specialPercentageEvents.size() > 5)
		{
			specialPercentageEvents.removeFirst();
		}

		for (ArrayDeque<Integer> queue : combatExpEarned.values())
		{
			if (queue.size() > 5)
			{
				queue.removeFirst();
			}
		}
	}
}

package com.freeeats;

import java.util.Arrays;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;

/**
 * Tells the overlay whether the local player is still pointed at something combat-related.
 *
 * AttackCooldownTracker decides when a real attack started. This class is only the quieter
 * display gate that keeps the cue alive while the fight context is still useful.
 */
final class CombatTargetClassifier
{
	private CombatTargetClassifier()
	{
	}

	static boolean isCombatTarget(Actor target)
	{
		if (target instanceof Player)
		{
			return true;
		}

		if (!(target instanceof NPC))
		{
			return false;
		}

		NPC npc = (NPC) target;
		NPCComposition composition = npc.getComposition();
		String[] actions = composition == null ? null : composition.getActions();
		return isAttackableNpc(npc.getCombatLevel(), actions);
	}

	static boolean isAttackableNpc(int combatLevel, String[] actions)
	{
		if (combatLevel > 0)
		{
			return true;
		}

		return actions != null && Arrays.stream(actions).anyMatch("Attack"::equals);
	}
}

package com.freeeats;

import java.util.regex.Pattern;

/**
 * Reads the game's consume messages and turns them into attack-delay ticks.
 *
 * The game message is important: it means the food really went through, so the tracker does not
 * punish failed clicks or menu attempts.
 */
final class FoodAttackDelay
{
	private static final int DEFAULT_FOOD_ATTACK_DELAY_TICKS = 3;
	private static final int FAST_FOOD_ATTACK_DELAY_TICKS = 2;

	private static final String GENERIC_EAT = "You eat";
	private static final String BARBARIAN_POTION = "You drink the lumpy potion";
	private static final String JUG_OF_WINE = "You drink the wine";
	private static final Pattern FOOD_MESSAGE = Pattern.compile(
		"^(" + GENERIC_EAT + "|" + BARBARIAN_POTION + "|" + JUG_OF_WINE + ")",
		Pattern.MULTILINE | Pattern.CASE_INSENSITIVE
	);

	private static final String FAST_GNOME_FOOD = "worm hole|tangled toads legs|veg ball|chocolate bomb|worm crunchies|toad crunchies|"
		+ "choc chip crunchies|spicy crunchies|fruit batta|cheese and tomato batta|toad batta|vegetable batta|worm batta";
	private static final String FAST_FOOD = "karambwan|halibut";
	private static final Pattern FAST_FOOD_MESSAGE = Pattern.compile(
		"(" + FAST_FOOD + "|" + FAST_GNOME_FOOD + ")",
		Pattern.CASE_INSENSITIVE
	);

	private FoodAttackDelay()
	{
	}

	static int fromChatMessage(String message)
	{
		if (message == null || !FOOD_MESSAGE.matcher(message).find())
		{
			return 0;
		}

		return FAST_FOOD_MESSAGE.matcher(message).find()
			? FAST_FOOD_ATTACK_DELAY_TICKS
			: DEFAULT_FOOD_ATTACK_DELAY_TICKS;
	}
}

package com.freeeats;

import java.awt.Color;

/**
 * A small, visual state for the user: red is early, orange is close, green is safe.
 */
enum FreeEatReadiness
{
	HIDDEN("", new Color(0, 0, 0, 0)),
	ONE("1", new Color(220, 45, 45)),
	TWO("2", new Color(255, 150, 35)),
	THREE("3", new Color(55, 190, 75));

	private final String text;
	private final Color color;

	FreeEatReadiness(String text, Color color)
	{
		this.text = text;
		this.color = color;
	}

	static FreeEatReadiness fromReadyTicks(int readyTicks)
	{
		if (readyTicks <= 0)
		{
			return HIDDEN;
		}

		if (readyTicks == 1)
		{
			return ONE;
		}

		if (readyTicks == 2)
		{
			return TWO;
		}

		return THREE;
	}

	boolean isVisible()
	{
		return this != HIDDEN;
	}

	String getText()
	{
		return text;
	}

	Color getColor()
	{
		return color;
	}
}

package com.freeeats;

/**
 * Owns the simple 1-2-3 count after the attack cooldown is gone.
 *
 * The attack tracker answers "can the player attack again yet?". This class turns that answer into
 * the user-facing free-eat cue, and resets whenever the context stops being useful.
 */
final class FreeEatState
{
	private static final int GREEN_TICKS = 3;

	private int readyTicks;
	private boolean sawAttack;
	private FreeEatReadiness readiness = FreeEatReadiness.HIDDEN;

	void reset()
	{
		readyTicks = 0;
		sawAttack = false;
		readiness = FreeEatReadiness.HIDDEN;
	}

	void onAttackStarted()
	{
		// A new attack begins a fresh weapon cooldown, so the food cue must disappear immediately.
		sawAttack = true;
		readyTicks = 0;
		readiness = FreeEatReadiness.HIDDEN;
	}

	void onGameTick(boolean usefulContext, int ticksUntilNextAttack)
	{
		if (!usefulContext)
		{
			reset();
			return;
		}

		if (!sawAttack)
		{
			readiness = FreeEatReadiness.HIDDEN;
			return;
		}

		if (ticksUntilNextAttack > 0)
		{
			readyTicks = 0;
			readiness = FreeEatReadiness.HIDDEN;
			return;
		}

		// Once cooldown is gone, count up to green and then hold there until combat context ends.
		readyTicks = Math.min(GREEN_TICKS, readyTicks + 1);
		readiness = FreeEatReadiness.fromReadyTicks(readyTicks);
	}

	FreeEatReadiness getReadiness()
	{
		return readiness;
	}

	int getReadyTicks()
	{
		return readyTicks;
	}
}

package com.freeeats;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the same 1-2-3 cue above the local player for people who watch the character model.
 */
final class FreeEatsAboveHeadOverlay extends Overlay
{
	private final Client client;
	private final FreeEatsPlugin plugin;
	private final FreeEatsConfig config;

	@Inject
	FreeEatsAboveHeadOverlay(Client client, FreeEatsPlugin plugin, FreeEatsConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		plugin.onOverlayRender();
		if (!plugin.isSelected(OverlayMode.ABOVE_HEAD) || !plugin.shouldShow())
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || client.getTopLevelWorldView() == null)
		{
			return null;
		}

		String text = plugin.getReadiness().getText();
		LocalPoint localLocation = localPlayer.getLocalLocation();
		int height = localPlayer.getLogicalHeight() + config.aboveHeadOffset();
		Point point = Perspective.localToCanvas(client, localLocation, client.getTopLevelWorldView().getPlane(), height);
		if (point == null)
		{
			return null;
		}

		graphics.setFont(new Font(FontManager.getRunescapeBoldFont().getName(), Font.BOLD, config.aboveHeadSize()));
		OverlayUtil.renderTextLocation(graphics, point, text, withAlpha(plugin.getReadiness().getColor(), config.aboveHeadOpacity()));
		return null;
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
	}
}

package com.freeeats;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("freeeats")
public interface FreeEatsConfig extends Config
{
	@ConfigItem(
		keyName = "overlayMode",
		name = "Overlay settings",
		description = "Choose where the free-eat cue is shown.",
		position = 0
	)
	default OverlayMode overlayMode()
	{
		return OverlayMode.INVENTORY;
	}

	@ConfigSection(
		name = "Inventory",
		description = "Inventory overlay settings.",
		position = 10,
		closedByDefault = true
	)
	String inventorySection = "inventorySection";

	@ConfigItem(
		keyName = "inventoryOpacity",
		name = "Opacity",
		description = "Opacity for the inventory food highlight.",
		position = 11,
		section = inventorySection
	)
	@Range(min = 0, max = 255)
	default int inventoryOpacity()
	{
		return 10;
	}

	@ConfigSection(
		name = "Above head",
		description = "Above-head overlay settings.",
