package com.freeeats;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Paints only supported hard-food slots, so the inventory itself becomes the cue.
 */
final class FreeEatsInventoryOverlay extends WidgetItemOverlay
{
	private final FreeEatsPlugin plugin;
	private final FreeEatsConfig config;

	@Inject
	FreeEatsInventoryOverlay(FreeEatsPlugin plugin, FreeEatsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		plugin.onOverlayRender();
		if (!plugin.isSelected(OverlayMode.INVENTORY) || !plugin.shouldShow() || !plugin.isHardFood(itemId))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		Color color = withAlpha(plugin.getReadiness().getColor(), config.inventoryOpacity());
		graphics.setColor(color);
		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
		graphics.setColor(withAlpha(plugin.getReadiness().getColor(), Math.min(255, config.inventoryOpacity() + 80)));
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), clamp(alpha));
	}

	private static int clamp(int value)
	{
		return Math.max(0, Math.min(255, value));
	}
}

package com.freeeats;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Free eats",
	description = "Shows when hard food can be eaten without delaying your next attack.",
	tags = {"combat", "pvp", "pvm", "food", "eat", "timer"}
)
public class FreeEatsPlugin extends Plugin
{
	private static final int COMBAT_LINGER_TICKS = 25;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FreeEatsConfig config;

	@Inject
	private HardFoodClassifier hardFoodClassifier;

	@Inject
	private AttackCooldownTracker cooldownTracker;

	@Inject
	private FreeEatsInventoryOverlay inventoryOverlay;

	@Inject
	private FreeEatsAboveHeadOverlay aboveHeadOverlay;

	@Inject
	private FreeEatsWidgetOverlay widgetOverlay;

	private final FreeEatState freeEatState = new FreeEatState();
	private boolean hasHardFood;
	private int combatContextTicks;
	private int lastRenderCycle = -1;

	@Provides
	FreeEatsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FreeEatsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(inventoryOverlay);
		overlayManager.add(aboveHeadOverlay);
		overlayManager.add(widgetOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(inventoryOverlay);
		overlayManager.remove(aboveHeadOverlay);
		overlayManager.remove(widgetOverlay);
		resetAllState();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		cooldownTracker.onVarbitChanged(event);
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed event)
	{
		cooldownTracker.onSoundEffectPlayed(event);
	}

	@Subscribe
	public void onFakeXpDrop(FakeXpDrop event)
	{
		if (cooldownTracker.onFakeXpDrop(event))
		{
			freeEatState.onAttackStarted();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (cooldownTracker.onStatChanged(event))
		{
			freeEatState.onAttackStarted();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		cooldownTracker.onChatMessage(event);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null && localPlayer.equals(event.getSource()) && CombatTargetClassifier.isCombatTarget(event.getTarget()))
		{
			combatContextTicks = COMBAT_LINGER_TICKS;
		}

		if (cooldownTracker.onInteractingChanged(event))
		{
			freeEatState.onAttackStarted();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			hasHardFood = hardFoodClassifier.hasHardFood(event.getItemContainer());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			resetAllState();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refreshHardFood();
		refreshCombatLinger();

		if (cooldownTracker.onGameTick(event))
		{
			freeEatState.onAttackStarted();
		}

		freeEatState.onGameTick(hasUsefulContext(), cooldownTracker.getTicksUntilNextAttack());
	}

	void onOverlayRender()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		int cycle = client.getGameCycle();
		if (lastRenderCycle == cycle)
		{
			return;
		}

		lastRenderCycle = cycle;
		cooldownTracker.onRender();
	}

	boolean isSelected(OverlayMode mode)
	{
		return config.overlayMode() == mode;
	}

	boolean shouldShow()
	{
		return hasUsefulContext() && getReadiness().isVisible();
	}

	FreeEatReadiness getReadiness()
	{
		return freeEatState.getReadiness();
	}

	boolean isHardFood(int itemId)
	{
		return hardFoodClassifier.isHardFood(itemId);
	}

	private boolean hasUsefulContext()
	{
		return hasHardFood && combatContextTicks > 0;
	}

	private void refreshHardFood()
	{
		hasHardFood = hardFoodClassifier.hasHardFood(client);
	}

	private void refreshCombatLinger()
	{
		Player localPlayer = client.getLocalPlayer();
		Actor target = localPlayer == null ? null : localPlayer.getInteracting();
		if (CombatTargetClassifier.isCombatTarget(target))
		{
			combatContextTicks = COMBAT_LINGER_TICKS;
			return;
		}

		if (combatContextTicks > 0)
		{
			combatContextTicks--;
		}
	}

	private void resetAllState()
	{
		hasHardFood = false;
		combatContextTicks = 0;
		lastRenderCycle = -1;
		freeEatState.reset();
		cooldownTracker.reset();
	}
}

package com.freeeats;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * A normal movable RuneLite overlay for players who prefer a fixed color indicator.
 */
final class FreeEatsWidgetOverlay extends OverlayPanel
{
	private static final int DEFAULT_SIZE = 12;
	private static final int ARC = 6;
	private static final Color INACTIVE_COLOR = new Color(45, 45, 45, 185);
	private static final Color BORDER_COLOR = new Color(255, 255, 255, 85);

	private final FreeEatsPlugin plugin;
	private final FreeEatsConfig config;

	@Inject
	FreeEatsWidgetOverlay(FreeEatsPlugin plugin, FreeEatsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setResizable(false);
		setPreferredSize(new Dimension(DEFAULT_SIZE, DEFAULT_SIZE));
		panelComponent.setBorder(new Rectangle(0, 0, 0, 0));
		panelComponent.setBackgroundColor(null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		plugin.onOverlayRender();
		if (!plugin.isSelected(OverlayMode.WIDGET))
		{
			return null;
		}

		FreeEatReadiness readiness = plugin.getReadiness();
		int size = config.widgetSize();
		setPreferredSize(new Dimension(size, size));
		panelComponent.getChildren().add(new ColorSquareComponent(getWidgetColor(readiness, plugin.shouldShow()), size));

		return super.render(graphics);
	}

	static Color getWidgetColor(FreeEatReadiness readiness, boolean shouldShow)
	{
		return shouldShow && readiness.isVisible() ? readiness.getColor() : INACTIVE_COLOR;
	}

	/**
	 * A tiny layout component that paints one square and nothing else.
	 *
	 * OverlayPanel keeps the square movable like a normal RuneLite widget, while this child avoids
	 * title text, number text, and any panel sizing surprises.
	 */
	private static final class ColorSquareComponent implements LayoutableRenderableEntity
	{
		private final Color color;
		private final int size;
		private Point preferredLocation = new Point();
		private Rectangle bounds = new Rectangle();

		private ColorSquareComponent(Color color, int size)
		{
			this.color = color;
			this.size = size;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			int squareSize = Math.max(1, size);
			bounds = new Rectangle(preferredLocation.x, preferredLocation.y, squareSize, squareSize);

			graphics.setColor(color);
			graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, ARC, ARC);
			graphics.setColor(BORDER_COLOR);
			graphics.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, ARC, ARC);

			return new Dimension(size, size);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point preferredLocation)
		{
			this.preferredLocation = preferredLocation;
		}

		@Override
		public void setPreferredSize(Dimension preferredSize)
		{
		}
	}
}

package com.freeeats;

import com.google.common.collect.ImmutableSet;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

/**
 * Decides whether an inventory item is normal hard food, not a fast-food or potion edge case.
 */
final class HardFoodClassifier
{
	private static final String EAT = "eat";
	private static final String DRINK = "drink";
	private static final String JUG_OF_WINE = "jug of wine";

	private static final Set<String> FAST_FOOD_NAMES = ImmutableSet.of(
		"karambwan",
		"halibut",
		"worm hole",
		"tangled toads legs",
		"veg ball",
		"chocolate bomb",
		"worm crunchies",
		"toad crunchies",
		"choc chip crunchies",
		"spicy crunchies",
		"fruit batta",
		"cheese and tomato batta",
		"toad batta",
		"vegetable batta",
		"worm batta"
	);

	private final ItemManager itemManager;

	@Inject
	HardFoodClassifier(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	boolean hasHardFood(ItemContainer inventory)
	{
		if (inventory == null)
		{
			return false;
		}

		for (Item item : inventory.getItems())
		{
			if (isHardFood(item.getId()))
			{
				return true;
			}
		}

		return false;
	}

	boolean hasHardFood(net.runelite.api.Client client)
	{
		return hasHardFood(client.getItemContainer(InventoryID.INV));
	}

	boolean isHardFood(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}

		int canonicalItemId = itemManager.canonicalize(itemId);
		ItemComposition composition = itemManager.getItemComposition(canonicalItemId);
		return isHardFood(composition.getName(), composition.getInventoryActions());
	}

	static boolean isHardFood(String itemName, String[] inventoryActions)
	{
		String name = normalize(itemName);
		if (name.isEmpty())
		{
			return false;
		}

		if (JUG_OF_WINE.equals(name))
		{
			return hasAction(inventoryActions, DRINK);
		}

		if (isFastFood(name) || name.contains("potion"))
		{
			return false;
		}

		return hasAction(inventoryActions, EAT);
	}

	private static boolean isFastFood(String name)
	{
		for (String fastFood : FAST_FOOD_NAMES)
		{
			if (name.contains(fastFood))
			{
				return true;
			}
		}

		return false;
	}

	private static boolean hasAction(String[] actions, String expected)
	{
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (action != null && expected.equals(normalize(action)))
			{
				return true;
			}
		}

		return false;
	}

	private static String normalize(String text)
	{
		if (text == null)
		{
			return "";
		}

		return text
			.toLowerCase(Locale.ROOT)
			.replace("'", "")
			.trim();
	}
}

