package com.freeeats;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FreeEatStateTest
{
	@Test
	public void countsUpAfterCooldownEnds()
	{
		FreeEatState state = new FreeEatState();

		state.onAttackStarted();
		state.onGameTick(true, 5);
		assertEquals(FreeEatReadiness.HIDDEN, state.getReadiness());

		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.ONE, state.getReadiness());

		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.TWO, state.getReadiness());

		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.THREE, state.getReadiness());

		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.THREE, state.getReadiness());
	}

	@Test
	public void resetOnNewAttack()
	{
		FreeEatState state = new FreeEatState();

		state.onAttackStarted();
		state.onGameTick(true, 0);
		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.TWO, state.getReadiness());

		state.onAttackStarted();
		assertEquals(FreeEatReadiness.HIDDEN, state.getReadiness());
		assertEquals(0, state.getReadyTicks());
	}

	@Test
	public void resetWhenCombatLingerExpires()
	{
		FreeEatState state = new FreeEatState();

		state.onAttackStarted();
		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.ONE, state.getReadiness());

		state.onGameTick(false, 0);
		assertEquals(FreeEatReadiness.HIDDEN, state.getReadiness());
		assertEquals(0, state.getReadyTicks());
	}

	@Test
	public void hidesAgainWhenEarlyFoodDelayIsApplied()
	{
		FreeEatState state = new FreeEatState();

		state.onAttackStarted();
		state.onGameTick(true, 0);
		assertEquals(FreeEatReadiness.ONE, state.getReadiness());

		state.onGameTick(true, 3);
		assertEquals(FreeEatReadiness.HIDDEN, state.getReadiness());
		assertEquals(0, state.getReadyTicks());
	}
}

