package com.freeeats;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class HardFoodClassifierTest
{
	private static final String[] EAT_ACTION = {"Eat", null, null, null, null};
	private static final String[] DRINK_ACTION = {"Drink", null, null, null, null};

	@Test
	public void includesNormalHardFood()
	{
		assertTrue(HardFoodClassifier.isHardFood("Anglerfish", EAT_ACTION));
		assertTrue(HardFoodClassifier.isHardFood("Shark", EAT_ACTION));
		assertTrue(HardFoodClassifier.isHardFood("Trout", EAT_ACTION));
		assertTrue(HardFoodClassifier.isHardFood("Salmon", EAT_ACTION));
		assertTrue(HardFoodClassifier.isHardFood("Dark crab", EAT_ACTION));
		assertTrue(HardFoodClassifier.isHardFood("Jug of wine", DRINK_ACTION));
	}

	@Test
	public void excludesFastFoodAndPotions()
	{
		assertFalse(HardFoodClassifier.isHardFood("Cooked karambwan", EAT_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Halibut", EAT_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Chocolate bomb", EAT_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Fruit batta", EAT_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Saradomin brew(4)", DRINK_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Super restore potion(4)", DRINK_ACTION));
	}

	@Test
	public void requiresAnEatActionUnlessItIsWine()
	{
		assertFalse(HardFoodClassifier.isHardFood("Shark", DRINK_ACTION));
		assertFalse(HardFoodClassifier.isHardFood("Jug of wine", EAT_ACTION));
	}
}
